parameters.script:
# keep-awake (Windows): a background session you start, check and stop.
# $env:BNTO_ARG_1 bnto home, _2 action, _3 duration (seconds | inf),
# _4 display (keep-on | allow-sleep), _5 activity simulation (idle seconds | off).
$ErrorActionPreference = 'Stop'
function Exit-Failure([string]$Message) {
    [Console]::Error.WriteLine("keep-awake: $Message")
    exit 2
}
$homeDir = [string]$env:BNTO_ARG_1
$action = [string]$env:BNTO_ARG_2
$duration = [string]$env:BNTO_ARG_3
$display = [string]$env:BNTO_ARG_4
$jiggle = [string]$env:BNTO_ARG_5
if (-not $homeDir) { Exit-Failure 'bnto home is unknown' }
if ($action -notin 'start', 'stop', 'status') { Exit-Failure "unknown action '$action'" }
if ($duration -ne 'inf' -and $duration -notmatch '^[1-9][0-9]*$') { Exit-Failure "bad duration '$duration'" }
if ($display -notin 'keep-on', 'allow-sleep') { Exit-Failure "bad display setting '$display'" }
if ($jiggle -ne 'off' -and $jiggle -notmatch '^[1-9][0-9]*$') { Exit-Failure "bad idle threshold '$jiggle'" }

# The session itself, run detached by a second, hidden PowerShell. The keep-
# awake request holds for as long as it runs; once you've been idle long
# enough it nudges the cursor 1px, which resets the idle timer chat apps read.
# Its values come from KEEP_AWAKE_* environment variables, never its code.
$session = {
    Add-Type -Namespace KeepAwake -Name Native -MemberDefinition @'
[DllImport("kernel32.dll")] public static extern uint SetThreadExecutionState(uint flags);
[DllImport("user32.dll")] public static extern void mouse_event(uint flags, int dx, int dy, uint data, System.UIntPtr extra);
[DllImport("user32.dll")] public static extern bool GetLastInputInfo(ref LastInput info);
public struct LastInput { public uint Size; public uint Time; }
'@
    # ES_CONTINUOUS | ES_SYSTEM_REQUIRED, plus ES_DISPLAY_REQUIRED to keep the screen on.
    $flags = [uint32]2147483649
    if ($env:KEEP_AWAKE_DISPLAY -eq 'keep-on') { $flags = [uint32]2147483651 }
    [void][KeepAwake.Native]::SetThreadExecutionState($flags)
    $ends = [long]$env:KEEP_AWAKE_UNTIL
    $threshold = [long]$env:KEEP_AWAKE_JIGGLE
    $info = New-Object KeepAwake.Native+LastInput
    $info.Size = 8
    $wrap = [long]4294967296
    while ($ends -eq 0 -or [DateTimeOffset]::UtcNow.ToUnixTimeSeconds() -lt $ends) {
        Start-Sleep -Seconds 15
        if ($threshold -gt 0 -and [KeepAwake.Native]::GetLastInputInfo([ref]$info)) {
            $ticks = ([long][Environment]::TickCount + $wrap) % $wrap
            $idle = (($ticks - $info.Time + $wrap) % $wrap) / 1000
            if ($idle -ge $threshold) {
                [KeepAwake.Native]::mouse_event(1, 1, 0, 0, [UIntPtr]::Zero)
                Start-Sleep -Milliseconds 150
                [KeepAwake.Native]::mouse_event(1, -1, 0, 0, [UIntPtr]::Zero)
            }
        }
    }
}
$encoded = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($session.ToString()))

$stateDir = Join-Path $homeDir 'state'
$state = Join-Path $stateDir 'keep-awake.json'
$now = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()

function Read-State {
    if (-not (Test-Path -LiteralPath $state)) { return $null }
    try { return Get-Content -LiteralPath $state -Raw | ConvertFrom-Json } catch { return $null }
}

# The session's pid, if the process at the recorded pid started at the
# recorded time and the session hasn't passed its end: a pid now used by
# another program never matches both. (Get-Process, not WMI, which is slow.)
function Get-SessionId($Saved) {
    if (-not $Saved -or -not $Saved.pid -or -not $Saved.started) { return $null }
    if ($Saved.until -and [long]$Saved.until -le $now) { return $null }
    try {
        $process = Get-Process -Id ([int]$Saved.pid)
        if ($process.StartTime.ToUniversalTime().Ticks -eq [long]$Saved.started) { return $process.Id }
    } catch {
        Write-Verbose "no session at pid $($Saved.pid): $_"
    }
    return $null
}

function Get-Plural([long]$Count, [string]$Unit) {
    if ($Count -eq 1) { return "1 $Unit" }
    return "$Count ${Unit}s"
}

function Get-Label([string]$Seconds) {
    if ($Seconds -eq 'inf') { return 'indefinitely' }
    $hours = [math]::Floor([long]$Seconds / 3600)
    $minutes = [math]::Floor(([long]$Seconds % 3600) / 60)
    if ($hours -eq 0) { return Get-Plural $minutes 'minute' }
    if ($minutes -eq 0) { return Get-Plural $hours 'hour' }
    return "$(Get-Plural $hours 'hour') $(Get-Plural $minutes 'minute')"
}

$saved = Read-State
$current = Get-SessionId $saved

if ($action -eq 'stop') {
    if ($current) {
        Stop-Process -Id $current -Force -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath $state -ErrorAction SilentlyContinue
        Write-Output 'Session ended -- this computer can sleep normally again.'
    } else {
        Remove-Item -LiteralPath $state -ErrorAction SilentlyContinue
        Write-Output 'No active session -- nothing to stop.'
    }
    exit 0
}

if ($action -eq 'status') {
    if (-not $current) {
        Write-Output 'No active session.'
        exit 0
    }
    if ($saved.until) {
        # Round up, so a fresh 30-minute session reads 30m, not 29m.
        $left = [math]::Max(0, [math]::Floor(([long]$saved.until - $now + 59) / 60))
        $remaining = '{0}h {1:D2}m remaining of {2}' -f [math]::Floor($left / 60), [int]($left % 60), $saved.label
    } else {
        $remaining = 'running indefinitely'
    }
    Write-Output "Session active -- $remaining."
    if ($saved.jiggle) { Write-Output 'Activity simulation: on' } else { Write-Output 'Activity simulation: off' }
    exit 0
}

# --- start ---
New-Item -ItemType Directory -Force -Path $stateDir | Out-Null
$replaced = ''
if ($current) {
    Stop-Process -Id $current -Force -ErrorAction SilentlyContinue
    $replaced = 'Replaced previous session -- '
}
Remove-Item -LiteralPath $state -ErrorAction SilentlyContinue

$label = Get-Label $duration
$until = 0
if ($duration -ne 'inf') { $until = $now + [long]$duration }
$env:KEEP_AWAKE_UNTIL = "$until"
$env:KEEP_AWAKE_DISPLAY = $display
$env:KEEP_AWAKE_JIGGLE = '0'
if ($jiggle -ne 'off') { $env:KEEP_AWAKE_JIGGLE = $jiggle }

# The same PowerShell that runs this step, hidden and detached: Start-Process
# hands it no handles, so bnto sees the step finish right away.
$powershell = (Get-Process -Id $PID).Path
$arguments = '-NoLogo', '-NoProfile', '-NonInteractive', '-EncodedCommand', $encoded
$process = Start-Process -FilePath $powershell -ArgumentList $arguments -WindowStyle Hidden -PassThru
Start-Sleep -Seconds 1
if ($process.HasExited) { Exit-Failure "the session stopped right away (exit $($process.ExitCode))" }

$started = "$($process.StartTime.ToUniversalTime().Ticks)"
$record = [ordered]@{ label = $label; pid = $process.Id; started = $started; jiggle = ($jiggle -ne 'off') }
if ($until) { $record.until = $until }
$record | ConvertTo-Json -Compress | Set-Content -LiteralPath $state -Encoding ASCII

if ($duration -eq 'inf') { $span = 'indefinitely (until you stop it)' } else { $span = "for $label" }
Write-Output "${replaced}Session started: staying awake $span."
if ($display -eq 'keep-on') { Write-Output 'Display: kept on' } else { Write-Output 'Display: allowed to sleep' }
if ($jiggle -eq 'off') {
    Write-Output 'Activity simulation: off'
} else {
    Write-Output "Activity simulation: on (nudges the cursor after ${jiggle}s idle)"
}
Write-Output 'Run keep-awake again with Action: Stop to end it early.'
